function longestSubarray(nums, limit) {
  const maxQueue = [];
  const minQueue = [];
  let maxHead = 0;
  let minHead = 0;
  let left = 0;
  let best = 0;

  for (let right = 0; right < nums.length; right++) {
    const value = nums[right];
    while (maxQueue.length > maxHead && maxQueue[maxQueue.length - 1] < value) {
      maxQueue.pop();
    }
    maxQueue.push(value);
    while (minQueue.length > minHead && minQueue[minQueue.length - 1] > value) {
      minQueue.pop();
    }
    minQueue.push(value);

    while (maxQueue[maxHead] - minQueue[minHead] > limit) {
      if (nums[left] === maxQueue[maxHead]) {
        maxHead++;
      }
      if (nums[left] === minQueue[minHead]) {
        minHead++;
      }
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

