function longestSubarray(nums, limit) {
  let best = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i; j < nums.length; j++) {
      const part = nums.slice(i, j + 1);
      if (Math.max(...part) - Math.min(...part) <= limit) best = Math.max(best, j - i + 1);
    }
  }
  return best;
}

