function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 10);
    const top = rand() < 0.2 ? 1000000000 : pick(1, 12);
    const nums = Array.from({ length: n }, () => pick(1, top));
    const limit = rand() < 0.15 ? 0 : rand() < 0.1 ? 1000000000 : pick(0, Math.min(top, 12));
    return [nums, limit];
  }
  const n = pick(1500, 2000);
  const mode = Math.floor(rand() * 3);
  const nums = [];
  if (mode === 0) {
    let value = 500000000;
    for (let i = 0; i < n; i++) {
      value = Math.min(1000000000, Math.max(1, value + pick(-1000, 1000)));
      nums.push(value);
    }
    return [nums, pick(0, 30000)];
  }
  if (mode === 1) {
    for (let i = 0; i < n; i++) nums.push(pick(1, 1000000000));
    return [nums, pick(500000000, 1000000000)];
  }
  for (let i = 0; i < n; i++) nums.push(pick(1, 50));
  return [nums, pick(0, 10)];
